from .modeller import Odunc


class KutuphaneServisi:
    def __init__(self):
        self.kitaplar = {}
        self.uyeler = {}
        self.kayitlar = []

    def kitap_ekle(self, kitap):
        self.kitaplar[kitap.id] = kitap

    def uye_ekle(self, uye):
        self.uyeler[uye.id] = uye

    def _aktif(self, kitap_id):
        return next((k for k in self.kayitlar if k.kitap_id == kitap_id and k.iade is None), None)

    def _toplam_odunc(self, uye_id):
        """Üyenin aktif (iade edilmemiş) ödünç sayısını döner."""
        return sum(1 for k in self.kayitlar if k.uye_id == uye_id and k.iade is None)

    def _ceza_hesapla(self, alinma: date, iade: date, uye_tur: str) -> float:
        """
        Ceza hesaplama:
        - Ödünç süresi 14 gün
        - İlk 7 gün gecikmesi: 2,50 TL/gün
        - 7. gün sonrası gecikmesi: 5,00 TL/gün
        - Maksimum ceza: 150 TL
        - Öğrenci ise %50 indirim (150 TL'den sonra)
        - 2 ondalığa yuvarlama
        """
        gecikme_gun = (iade - alinma).days - 14

        if gecikme_gun <= 0:
            return 0.0

        gecikme_gun = max(0, gecikme_gun)

        # İlk 7 gün: 2,50 TL, sonrası: 5,00 TL
        ceza = gecikme_gun * 2.50 if gecikme_gun <= 7 else (7 * 2.50) + (gecikme_gun - 7) * 5.00

        # Maksimum 150 TL
        ceza = min(ceza, 150.0)

        # Öğrenci indirimini uygula (150 TL'den sonra)
        if uye_tur == "ogrenci":
            ceza = ceza * 0.5

        # 2 ondalığa yuvarla
        return round(ceza, 2)

    def odunc_ver(self, kitap_id, uye_id, tarih):
        """Kitabı üyeye verir. Kitap/üye yoksa ya da kitap zaten ödünçteyse ValueError."""
        if kitap_id not in self.kitaplar or uye_id not in self.uyeler:
            raise ValueError("kitap ya da üye bulunamadı")
        if self._aktif(kitap_id):
            raise ValueError("kitap zaten ödünçte")

        # Kitap sayısını kontrol et
        uye = self.uyeler[uye_id]
        aktif_sayi = self._toplam_odunc(uye_id)
        max_sira = 5 if uye.tur == "ogrenci" else 3

        if aktif_sayi >= max_sira:
            raise ValueError(f"Ödünç sınırı aşıldı ({aktif_sayi}/{max_sira})")

        kayit = Odunc(kitap_id, uye_id, tarih)
        self.kayitlar.append(kayit)
        return kayit

    def iade_al(self, kitap_id, tarih):
        """Kitabın iadesini alır ve ödünç kaydını döndürür. Kitap ödünçte değilse ValueError."""
        kayit = self._aktif(kitap_id)
        if kayit is None:
            raise ValueError("kitap ödünçte değil")

        uye = self.uyeler[kayit.uye_id]
        ceza = self._ceza_hesapla(kayit.alinma, tarih, uye.tur)
        kayit.iade = tarih
        kayit.ceza = ceza

        return kayit

    def oduncteki_kitaplar(self, uye_id):
        return sorted(k.kitap_id for k in self.kayitlar if k.uye_id == uye_id and k.iade is None)

    def toplam_ceza(self, uye_id):
        """Üyenin iade edilmiş tüm ödünçlerinin cezaları toplamı."""
        return round(sum(k.ceza for k in self.kayitlar if k.uye_id == uye_id and k.iade is not None), 2)

